147	/**
148	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
149	 * @param {Record<string, string | string[] | null> | undefined} varyDirectives
150	 * @returns {boolean}
151	 */
152	function revalidationResponseAddsVary (result, varyDirectives) {
153	  if (!varyDirectives) {
154	    return false
155	  }
156	
157	  for (const key in varyDirectives) {
158	    if (result.vary == null || !Object.hasOwn(result.vary, key)) {
159	      return true
160	    }
161	  }
162	
163	  return false
164	}
