202	/**
203	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
204	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} cacheControlDirectives
205	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheOptions['type']} cacheType
206	 * @returns {boolean}
207	 */
208	function isStale (result, cacheControlDirectives, cacheType) {
209	  const now = Date.now()
210	  if (now > result.staleAt) {
211	    // Response is stale
212	    if (!staleResponseRequiresRevalidation(result, cacheType) && cacheControlDirectives?.['max-stale']) {
213	      // There's a threshold where we can serve stale responses, let's see if
214	      //  we're in it
215	      // https://www.rfc-editor.org/rfc/rfc9111.html#name-max-stale
216	      const gracePeriod = result.staleAt + (cacheControlDirectives['max-stale'] * 1000)
217	      return now > gracePeriod
218	    }
219	
220	    return true
221	  }
222	
223	  if (cacheControlDirectives?.['min-fresh']) {
224	    // https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.1.3
225	
226	    // At this point, staleAt is always > now
227	    const timeLeftTillStale = result.staleAt - now
228	    const threshold = cacheControlDirectives['min-fresh'] * 1000
229	
230	    return timeLeftTillStale <= threshold
231	  }
232	
233	  return false
234	}
