'use strict'

const { createServer } = require('node:http')
const { once } = require('node:events')
const { Client, interceptors } = require('./index.js')

async function main () {
  let hits = 0
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    hits++
    res.statusCode = 404
    res.setHeader('cache-control', 'public, max-age=60')
    res.end(`body ${hits}`)
  }).listen(0)

  await once(server, 'listening')
  const origin = `http://localhost:${server.address().port}`

  const writes = []
  const gets = []
  const client = new Client(origin).compose(interceptors.cache({
    store: {
      get (key) {
        gets.push(key.method)
        return undefined
      },
      createWriteStream (key) {
        writes.push(key.method)
        return undefined
      },
      delete () {}
    }
  }))

  for (const method of ['POST', 'PUT', 'PATCH', 'DELETE']) {
    const res = await client.request({ origin, method, path: '/' })
    await res.body.text()
  }

  await client.close()
  server.close()

  console.log('store.get calls:', gets)
  console.log('store.createWriteStream calls:', writes)
  if (gets.length !== 0 || writes.length !== 0) {
    console.log('FAIL: unsafe methods touched the cache')
    process.exitCode = 1
  } else {
    console.log('OK: unsafe methods never read or wrote the cache')
  }
}

main()

